update public.site_faqs set answer='Report의 관광 자원 15곳은 녹색 계열의 정사각형 픽셀 아트 카드로 소개합니다. 카드는 두 줄로 배치된 가로 목록이며, 픽셀 이미지를 누르면 Windows 95 탐색기 스타일의 상세 팝업에서 소개·체험 프로그램·방문자 후기를 볼 수 있습니다. 15곳 모두 상세 탐색기의 모션 카드뉴스 폴더에서 사진과 관람 포인트를 볼 수 있습니다. 부산현대미술관 편은 서로 다른 전시 사진 5장으로 구성했습니다. API가 갱신돼도 카드 이미지는 유지됩니다.', keywords=array['픽셀','픽셀 이미지','8비트','8bit','카드 이미지','녹색 이미지','모션 카드뉴스','모션 카드','탐색기 영상'], embedding=null, updated_at=now() where slug='report-pixel';
